#!/usr/bin/env node
'use strict';

const USAGE = 'Usage: node slug.js "<title>"';

// Letters that Unicode decomposition does not split into a plain letter and an accent.
const SPECIAL_LETTERS = { ß: 'ss', æ: 'ae', œ: 'oe', ø: 'o', ł: 'l', đ: 'd' };

function slugify(title) {
  return title
    .toLowerCase()
    .replace(/[ßæœøłđ]/g, (letter) => SPECIAL_LETTERS[letter])
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function main(args) {
  if (args.length === 1 && (args[0] === '--help' || args[0] === '-h')) {
    console.log(USAGE);
    return 0;
  }
  const slug = slugify(args.join(' '));
  if (!slug) {
    console.error(USAGE);
    return 1;
  }
  console.log(slug);
  return 0;
}

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}

module.exports = { slugify };

